@router.get("/api/v1/builds/{build_id}/live-logs")
async def stream_build_logs(
    build_id: str,
    log_streamer: BuildLogStreamer = Depends(get_log_streamer),
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    stmt = select(BuildJob).join(Project).where(
        BuildJob.id == build_id,
        Project.organization_id == current_user.organization_id
    )
    res = await db.execute(stmt)
    build = res.scalar_one_or_none()
    if not build:
        raise HTTPException(status_code=404, detail="Build not found or unauthorized")

    async def log_generator():
        async for log_line in log_streamer.tail_logs(build_id):
            yield {"event": "log_chunk", "data": json.dumps({"build_id": build_id, "line": log_line})}

    return EventSourceResponse(log_generator())
